package com.metaverse.coin.strategy.htx.persistence;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.sql.PreparedStatement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import static com.metaverse.coin.strategy.htx.service.HtxTrendExitContractV5.*;

/** Atomic v5 state/decision/intent store. It has no exchange client and cannot send orders. */
@Repository
public class HtxTrendExitStateStoreV5 {
    private static final ObjectMapper JSON=new ObjectMapper();
    private final JdbcTemplate jdbc;private final TransactionTemplate tx;
    public HtxTrendExitStateStoreV5(JdbcTemplate jdbc,PlatformTransactionManager tm){this.jdbc=jdbc;this.tx=new TransactionTemplate(tm);}
    public enum AppendStatus{APPLIED,IDEMPOTENT,REVISION_CONFLICT,FENCED}
    public enum FillStatus{APPLIED,IDEMPOTENT}
    public record Lease(String scopeKey,String ownerId,long ownerToken,LocalDateTime leaseUntil,boolean acquired){}
    public record InitializeRequest(long positionId,long positionEpoch,long accountId,long ownerToken,String strategyInstance,BigDecimal confirmedQty,EntryThesis contract,Policy policy,State state){}
    public record AppendRequest(long positionId,long positionEpoch,long expectedRevision,long ownerToken,String eventKey,String decisionKey,String accountLabel,String contractCode,BigDecimal confirmedQty,EntryThesis contract,Policy policy,State prior,Event event,Transition transition,boolean createIntent,LocalDateTime observedAt){}
    public record FillRequest(long intentId,long accountId,long positionId,long positionEpoch,String exchangeOrderId,String tradeId,BigDecimal filledQty,BigDecimal fillPrice,BigDecimal fee,BigDecimal allocatedEntryFee,BigDecimal allocatedFunding,LocalDateTime filledAt){}
    public record FillResult(FillStatus status,BigDecimal confirmedQty,String executionState){}
    public record GuardUpdate(long accountId,String strategyFamily,String contractCode,String side,String structureId,long expectedRevision,int attempts,BigDecimal realizedLoss,BigDecimal fees,String exitReason,String status,String evidenceJson,LocalDateTime updatedAt){}
    public record ReentryDecision(boolean allowed,String reason){}

    public Lease claim(String scope,String owner,LocalDateTime now,long leaseMillis){
        require(scope!=null&&!scope.isBlank()&&owner!=null&&!owner.isBlank(),"lease identity required");require(leaseMillis>0,"lease duration required");
        return Objects.requireNonNull(tx.execute(status->{
            List<Lease> rows=jdbc.query("SELECT scope_key,owner_id,owner_token,lease_until FROM htx_trend_exit_owner_lease_v5 WHERE scope_key=? FOR UPDATE",(rs,n)->new Lease(rs.getString(1),rs.getString(2),rs.getLong(3),rs.getTimestamp(4).toLocalDateTime(),false),scope);
            LocalDateTime until=now.plusNanos(leaseMillis*1_000_000L);
            if(rows.isEmpty()){jdbc.update("INSERT INTO htx_trend_exit_owner_lease_v5(scope_key,owner_id,owner_token,lease_until,renewed_at) VALUES(?,?,?,?,?)",scope,owner,1L,Timestamp.valueOf(until),Timestamp.valueOf(now));return new Lease(scope,owner,1L,until,true);}
            Lease current=rows.get(0);if(!current.ownerId().equals(owner)&&current.leaseUntil().isAfter(now))return current;
            long token=current.ownerId().equals(owner)?current.ownerToken():current.ownerToken()+1;
            jdbc.update("UPDATE htx_trend_exit_owner_lease_v5 SET owner_id=?,owner_token=?,lease_until=?,renewed_at=? WHERE scope_key=?",owner,token,Timestamp.valueOf(until),Timestamp.valueOf(now),scope);return new Lease(scope,owner,token,until,true);
        }));
    }

    public long initialize(InitializeRequest r){return Objects.requireNonNull(tx.execute(status->{
        require(r.contract().position_epoch()==r.positionEpoch(),"position epoch mismatch");require(r.contract().policy_hash().equals(canonicalHash(r.policy())),"policy hash mismatch");
        Integer leased=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_owner_lease_v5 WHERE scope_key=? AND owner_token=?",Integer.class,scopeKey(r.contract()),r.ownerToken());require(leased!=null&&leased==1,"owner token is not leased");
        GeneratedKeyHolder keys=new GeneratedKeyHolder();jdbc.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO htx_trend_entry_contract(position_id,position_epoch,account_id,strategy_instance,engine_version,policy_hash,contract_hash,structure_id,contract_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",new String[]{"id"});statement.setLong(1,r.positionId());statement.setLong(2,r.positionEpoch());statement.setLong(3,r.accountId());statement.setString(4,r.strategyInstance());statement.setString(5,r.contract().engine_version());statement.setString(6,r.contract().policy_hash());statement.setString(7,r.contract().contractHash());statement.setString(8,r.contract().structure_id());statement.setString(9,canonicalJson(r.contract()));statement.setTimestamp(10,Timestamp.valueOf(LocalDateTime.now()));return statement;},keys);
        long contractId=Objects.requireNonNull(keys.getKey()).longValue();jdbc.update("INSERT INTO htx_trend_exit_state_v5(position_id,position_epoch,revision,contract_id,owner_token,last_bar_end,last_event_key,phase,execution_state,confirmed_remaining_qty,state_json,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",r.positionId(),r.positionEpoch(),r.state().revision(),contractId,r.ownerToken(),r.state().last_bar_end_ms(),"",r.state().phase().name(),r.state().execution_state().name(),r.confirmedQty(),canonicalJson(r.state()),Timestamp.valueOf(LocalDateTime.now()));return contractId;
    }));}

    public AppendStatus compareAndAppend(AppendRequest r){validate(r);return Objects.requireNonNull(tx.execute(status->{
        Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_decision WHERE decision_key=?",Integer.class,r.decisionKey());if(exists!=null&&exists>0)return AppendStatus.IDEMPOTENT;
        Integer owner=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_owner_lease_v5 WHERE scope_key=? AND owner_token=? AND lease_until>=?",Integer.class,scopeKey(r.contract()),r.ownerToken(),Timestamp.valueOf(r.observedAt()));if(owner==null||owner==0)return AppendStatus.FENCED;
        List<String> persisted=jdbc.query("SELECT state_json FROM htx_trend_exit_state_v5 WHERE position_id=? AND position_epoch=? AND revision=? AND owner_token=? FOR UPDATE",(rs,n)->rs.getString(1),r.positionId(),r.positionEpoch(),r.expectedRevision(),r.ownerToken());if(persisted.isEmpty()||!canonicalJson(r.prior()).equals(persisted.get(0)))return AppendStatus.REVISION_CONFLICT;
        State next=r.transition().state();int changed=jdbc.update("UPDATE htx_trend_exit_state_v5 SET revision=?,last_bar_end=?,last_event_key=?,phase=?,execution_state=?,confirmed_remaining_qty=?,state_json=?,updated_at=? WHERE position_id=? AND position_epoch=? AND revision=? AND owner_token=?",next.revision(),next.last_bar_end_ms(),r.eventKey(),next.phase().name(),next.execution_state().name(),r.confirmedQty(),canonicalJson(next),Timestamp.valueOf(r.observedAt()),r.positionId(),r.positionEpoch(),r.expectedRevision(),r.ownerToken());if(changed==0)return AppendStatus.REVISION_CONFLICT;
        Decision decision=r.transition().decision();Map<String,Object> evidence=new LinkedHashMap<>();evidence.put("schema",VERSION);evidence.put("event",r.event());evidence.put("decision",decision);evidence.put("state",next);evidence.put("policy",r.policy());
        boolean wantsIntent=r.createIntent()&&(decision.action()==Action.PARTIAL_CLOSE||decision.action()==Action.FULL_CLOSE);Integer active=wantsIntent?jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_intent_v5 WHERE position_id=? AND position_epoch=? AND status IN ('PENDING','PARTIAL','SENT','UNKNOWN')",Integer.class,r.positionId(),r.positionEpoch()):0;boolean create=wantsIntent&&(active==null||active==0);
        jdbc.update("INSERT INTO htx_trend_exit_decision(decision_key,position_id,account_id,account_label,contract_code,side,primary_model,engine_version,exit_phase,suggested_action,executed_action,execution_block_reason,reference_price,protection_price,current_net_pnl,execution_readiness,target_remaining_contracts,evidence_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",r.decisionKey(),r.positionId(),r.contract().account_id(),r.accountLabel(),r.contractCode(),r.contract().side().name(),r.contract().model_id(),VERSION,decision.phase().name(),decision.action().name(),"NONE",create?null:wantsIntent?"RECONCILE_EXISTING_INTENT":"OBSERVE_OR_NON_ORDER_ACTION",r.event().reference_price(),decision.active_soft_boundary(),r.event().current_net_pnl(),create?"PERSISTED_INTENT":wantsIntent?"RECONCILE_PENDING_INTENT":"NO_ORDER",decision.target_remaining_contracts(),canonicalJson(evidence),Timestamp.valueOf(r.observedAt()));
        if(create)jdbc.update("INSERT INTO htx_trend_exit_intent_v5(decision_key,position_id,position_epoch,state_revision,owner_token,client_order_id,target_remaining_qty,status,payload_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",r.decisionKey(),r.positionId(),r.positionEpoch(),next.revision(),r.ownerToken(),clientOrderId(r.decisionKey()),BigDecimal.valueOf(decision.target_remaining_contracts()),"PENDING",canonicalJson(evidence),Timestamp.valueOf(r.observedAt()),Timestamp.valueOf(r.observedAt()));return AppendStatus.APPLIED;
    }));}

    public boolean adoptOwner(EntryThesis contract,long positionId,long epoch,long oldToken,long newToken,LocalDateTime at){Integer leased=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_owner_lease_v5 WHERE scope_key=? AND owner_token=? AND lease_until>=?",Integer.class,scopeKey(contract),newToken,Timestamp.valueOf(at));return leased!=null&&leased>0&&jdbc.update("UPDATE htx_trend_exit_state_v5 SET owner_token=?,updated_at=? WHERE position_id=? AND position_epoch=? AND owner_token=?",newToken,Timestamp.valueOf(at),positionId,epoch,oldToken)==1;}

    public AppendStatus updateReentryGuard(GuardUpdate r){return Objects.requireNonNull(tx.execute(status->{String key=guardKey(r.accountId(),r.strategyFamily(),r.contractCode(),r.side(),r.structureId());Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_reentry_guard_v5 WHERE guard_key=?",Integer.class,key);if(exists==null||exists==0){if(r.expectedRevision()!=-1)return AppendStatus.REVISION_CONFLICT;jdbc.update("INSERT INTO htx_trend_reentry_guard_v5(guard_key,account_id,strategy_family,contract_code,side,structure_id,revision,same_structure_attempts,accumulated_realized_loss,accumulated_fees,exit_reason,status,evidence_json,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",key,r.accountId(),r.strategyFamily(),r.contractCode(),r.side(),r.structureId(),0L,r.attempts(),r.realizedLoss(),r.fees(),r.exitReason(),r.status(),r.evidenceJson(),Timestamp.valueOf(r.updatedAt()));return AppendStatus.APPLIED;}int changed=jdbc.update("UPDATE htx_trend_reentry_guard_v5 SET revision=?,same_structure_attempts=?,accumulated_realized_loss=?,accumulated_fees=?,exit_reason=?,status=?,evidence_json=?,updated_at=? WHERE guard_key=? AND revision=?",r.expectedRevision()+1,r.attempts(),r.realizedLoss(),r.fees(),r.exitReason(),r.status(),r.evidenceJson(),Timestamp.valueOf(r.updatedAt()),key,r.expectedRevision());return changed==1?AppendStatus.APPLIED:AppendStatus.REVISION_CONFLICT;}));}
    public ReentryDecision evaluateReentry(long accountId,String family,String contract,String side,String structure,BigDecimal budget,boolean sameStructureEnabled){List<Map<String,Object>> exact=jdbc.queryForList("SELECT status,same_structure_attempts FROM htx_trend_reentry_guard_v5 WHERE guard_key=?",guardKey(accountId,family,contract,side,structure));if(!exact.isEmpty()){String status=String.valueOf(exact.get(0).get("status"));int attempts=((Number)exact.get(0).get("same_structure_attempts")).intValue();if("UNKNOWN".equals(status)||"IN_FLIGHT".equals(status))return new ReentryDecision(false,"PREVIOUS_EXIT_UNRESOLVED");if(!sameStructureEnabled||attempts>=1||!"RESET_CONFIRMED".equals(status))return new ReentryDecision(false,"SAME_STRUCTURE_LOCKED");}BigDecimal used=jdbc.queryForObject("SELECT COALESCE(SUM(accumulated_realized_loss+accumulated_fees),0) FROM htx_trend_reentry_guard_v5 WHERE account_id=? AND contract_code=? AND side=?",BigDecimal.class,accountId,contract,side);if(budget==null||used==null||used.compareTo(budget)>=0)return new ReentryDecision(false,"ACCOUNT_SYMBOL_SIDE_BUDGET_EXHAUSTED");return new ReentryDecision(true,"REENTRY_GATES_CLEAR");}

    public FillResult applyUniqueFill(FillRequest r){return Objects.requireNonNull(tx.execute(status->{Integer duplicate=jdbc.queryForObject("SELECT COUNT(*) FROM htx_trend_exit_fill_v5 WHERE account_id=? AND trade_id=?",Integer.class,r.accountId(),r.tradeId());if(duplicate!=null&&duplicate>0)return new FillResult(FillStatus.IDEMPOTENT,jdbc.queryForObject("SELECT confirmed_remaining_qty FROM htx_trend_exit_state_v5 WHERE position_id=?",BigDecimal.class,r.positionId()),"UNCHANGED");Map<String,Object> intent=jdbc.queryForMap("SELECT position_epoch,target_remaining_qty FROM htx_trend_exit_intent_v5 WHERE id=? FOR UPDATE",r.intentId());require(((Number)intent.get("position_epoch")).longValue()==r.positionEpoch(),"fill epoch mismatch");Map<String,Object> row=jdbc.queryForMap("SELECT revision,confirmed_remaining_qty,state_json FROM htx_trend_exit_state_v5 WHERE position_id=? FOR UPDATE",r.positionId());BigDecimal remaining=(BigDecimal)row.get("confirmed_remaining_qty"),target=(BigDecimal)intent.get("target_remaining_qty"),nextQty=remaining.subtract(r.filledQty());require(r.filledQty().signum()>0&&nextQty.compareTo(target)>=0,"fill exceeds intent target");boolean complete=nextQty.compareTo(target)==0;State prior=decode(String.valueOf(row.get("state_json")));State next=new State(prior.revision()+1,complete&&target.signum()==0?ProfitPhase.CLOSED:complete?ProfitPhase.RUNNER:prior.phase(),complete?ExecutionState.CONFIRMED:ExecutionState.PARTIAL,prior.last_bar_end_ms(),prior.eligible_bars(),prior.structure_failure_bars(),prior.best_close(),prior.active_soft_boundary(),prior.active_boundary_id(),prior.pending_soft_boundary(),prior.pending_boundary_id(),prior.soft_breach_bars(),prior.armed_bar_end_ms(),prior.partial_stage()+(complete&&target.signum()>0?1:0),prior.extension_achieved());jdbc.update("INSERT INTO htx_trend_exit_fill_v5(intent_id,account_id,exchange_order_id,trade_id,filled_qty,fill_price,fee,allocated_entry_fee,allocated_funding,filled_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",r.intentId(),r.accountId(),r.exchangeOrderId(),r.tradeId(),r.filledQty(),r.fillPrice(),r.fee(),r.allocatedEntryFee(),r.allocatedFunding(),Timestamp.valueOf(r.filledAt()),Timestamp.valueOf(r.filledAt()));jdbc.update("UPDATE htx_trend_exit_intent_v5 SET status=?,updated_at=? WHERE id=?",complete?"CONFIRMED":"PARTIAL",Timestamp.valueOf(r.filledAt()),r.intentId());jdbc.update("UPDATE htx_trend_exit_state_v5 SET revision=?,phase=?,execution_state=?,confirmed_remaining_qty=?,state_json=?,updated_at=? WHERE position_id=? AND position_epoch=? AND revision=?",next.revision(),next.phase().name(),next.execution_state().name(),nextQty,canonicalJson(next),Timestamp.valueOf(r.filledAt()),r.positionId(),r.positionEpoch(),((Number)row.get("revision")).longValue());return new FillResult(FillStatus.APPLIED,nextQty,next.execution_state().name());}));}

    public long intentId(String key){return jdbc.queryForObject("SELECT id FROM htx_trend_exit_intent_v5 WHERE decision_key=?",Long.class,key);}
    public long revision(long position){return jdbc.queryForObject("SELECT revision FROM htx_trend_exit_state_v5 WHERE position_id=?",Long.class,position);}
    public static String scopeKey(EntryThesis c){return c.account_id()+":"+c.strategy_instance();}
    public static String decisionKey(long position,long epoch,String event,String policy){return "v5:"+position+":"+epoch+":"+canonicalHash(Map.of("event",event,"policy",policy));}
    public static String clientOrderId(String key){BigInteger limit=BigInteger.TEN.pow(18).subtract(BigInteger.ONE);return new BigInteger(canonicalHash(key),16).mod(limit).add(BigInteger.ONE).toString();}
    public static BigDecimal pendingDelta(BigDecimal confirmed,BigDecimal target,BigDecimal filled,BigDecimal inFlight){BigDecimal delta=confirmed.subtract(target).subtract(filled).subtract(inFlight);return delta.signum()>0?delta:BigDecimal.ZERO;}
    public static String guardKey(long account,String family,String contract,String side,String structure){return canonicalHash(Map.of("account",account,"family",family,"contract",contract,"side",side,"structure",structure));}
    private static void validate(AppendRequest r){require(r.prior().revision()==r.expectedRevision(),"prior revision mismatch");require(r.transition().state().revision()==r.expectedRevision()+1,"next revision mismatch");require(r.contract().position_epoch()==r.positionEpoch(),"position epoch mismatch");require(r.contract().policy_hash().equals(canonicalHash(r.policy())),"policy hash mismatch");String expected=canonicalHash(Map.of("contract",r.contract(),"state",r.prior(),"event",r.event(),"policy",r.policy()));require(expected.equals(r.transition().decision().input_hash()),"decision input hash mismatch");long target=r.transition().decision().target_remaining_contracts();require(target>=0&&BigDecimal.valueOf(target).compareTo(r.confirmedQty())<=0,"target outside confirmed quantity");}
    private static State decode(String value){try{return JSON.readValue(value,State.class);}catch(JsonProcessingException e){throw new IllegalStateException("invalid persisted v5 state",e);}}
    private static void require(boolean ok,String message){if(!ok)throw new IllegalArgumentException(message);}
}
